sas:
DATA customer_new;
    SET customer;
    IF age > 18 THEN status = 'Adult';
    ELSE status = 'Minor';
RUN;

PROC SORT DATA=work.sales OUT=work.sales_unique NODUPKEY;
    BY region DESCENDING amount;
RUN;

PROC TRANSPOSE DATA=work.monthly_sales OUT=work.pivoted;
    BY store_id;
    ID month;
    VAR revenue;
RUN;
